output_text:
[
  {
    "id": "no_cart_single_file_aisles",
    "text": "Shopping carts are prohibited in single-file shelf aisles where shelves line both sides of a one-cell-wide passage.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_entry_to_single_file",
    "text": "A shopper must not push a cart from a wider aisle into a single-file shelf aisle.",
    "abstraction": {
      "state_properties": {
        "wideAisle": {
          "ge": [
            "freeWidthH",
            6
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        }
      },
      "events": {
        "enterSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "wideAisle",
              {
                "or": [
                  "N",
                  "S",
                  "E",
                  "W"
                ]
              }
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterSingleFileWithCart"
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "After parking a cart at the mouth of a single-file aisle, the shopper is obliged to recover the cart before leaving.",
    "abstraction": {
      "state_properties": {
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "parkCartForAisle": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart",
              "cartParkingBay"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recoverParkedCart": {
          "pre": {
            "and": [
              "INTERACT",
              {
                "not": "hasCart"
              },
              "cartParkingBay"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCartForAisle",
      "discharge": "recoverParkedCart"
    }
  },
  {
    "id": "cart_required_for_normal_shelf_service",
    "text": "When interacting with shelves from an ordinary aisle rather than inside a single-file aisle, the shopper must have the cart with them.",
    "abstraction": {
      "state_properties": {
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "ordinaryShelfServiceCell": {
          "and": [
            "adjShelf",
            {
              "not": "singleFileShelfAisle"
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "ordinaryShelfServiceCell",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "park_cart_only_at_bays",
    "text": "A shopper may leave their cart only at designated aisle-mouth parking bays.",
    "abstraction": {
      "state_properties": {
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        }
      },
      "events": {
        "leaveCart": {
          "pre": {
            "and": [
              "INTERACT",
              "hasCart"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "leaveCart",
          {
            "not": "cartParkingBay"
          }
        ]
      }
    }
  },
  {
    "id": "no_ordinary_travel_without_cart",
    "text": "Except in the entrance/cart area, cart-parking bays, and single-file shelf aisles, shoppers should not travel through the store without their cart.",
    "abstraction": {
      "state_properties": {
        "entranceCartArea": {
          "or": [
            "at(0,7)",
            "at(1,7)"
          ]
        },
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            "shelfE",
            "shelfW"
          ]
        },
        "allowedNoCartPlace": {
          "or": [
            "entranceCartArea",
            "cartParkingBay",
            "singleFileShelfAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          {
            "or": [
              "N",
              "S",
              "E",
              "W"
            ]
          },
          {
            "not": "hasCart"
          },
          {
            "not": "allowedNoCartPlace"
          }
        ]
      }
    }
  },
  {
    "id": "eastbound_cart_flow",
    "text": "Cart traffic in broad horizontal aisles follows a one-way eastbound flow, so shoppers with carts must not move west there.",
    "abstraction": {
      "state_properties": {
        "broadHorizontalAisle": {
          "ge": [
            "freeWidthH",
            12
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "broadHorizontalAisle",
          "W"
        ]
      }
    }
  },
  {
    "id": "interact_only_at_service_locations",
    "text": "Interactions should occur only at recognized service locations: the entrance cart station, aisle-mouth cart bays, or cells adjacent to shelves.",
    "abstraction": {
      "state_properties": {
        "entranceCartStation": "at(1,7)",
        "cartParkingBay": {
          "or": [
            "at(3,3)",
            "at(6,3)"
          ]
        },
        "serviceLocation": {
          "or": [
            "entranceCartStation",
            "cartParkingBay",
            "adjShelf"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          {
            "not": "serviceLocation"
          }
        ]
      }
    }
  }
]
